def _security() -> None:
    """Row-level security, grants for the app role, append-only audit (Phase 2: tenancy, DD-02, DD-11)."""
    from app.models import APPEND_ONLY, TENANT_TABLES
    for sch in SCHEMAS:
        op.execute(f"GRANT USAGE ON SCHEMA {sch} TO crewboard_app")
        op.execute(f"GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA {sch} TO crewboard_app")
        op.execute(f"GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA {sch} TO crewboard_app")
    tenant = "NULLIF(current_setting('app.tenant_id', true), '')::uuid"
    user = "NULLIF(current_setting('app.user_id', true), '')::uuid"
    for t in TENANT_TABLES:
        op.execute(f"ALTER TABLE {t} ENABLE ROW LEVEL SECURITY")
        if t == "platform.membership":
            # A signed-in user can see their own memberships in every tenant (to pick the active tenant).
            op.execute(f"CREATE POLICY tenant_isolation ON {t} USING (tenant_id = {tenant} OR user_id = {user}) "
                       f"WITH CHECK (tenant_id = {tenant})")
        else:
            op.execute(f"CREATE POLICY tenant_isolation ON {t} USING (tenant_id = {tenant}) WITH CHECK (tenant_id = {tenant})")
    for t in APPEND_ONLY:
        op.execute(f"REVOKE UPDATE, DELETE ON {t} FROM crewboard_app")
    # Tenants: readable only when active or a member; writes go through the platform service (owner role in admin tools).
    op.execute("ALTER TABLE platform.tenant ENABLE ROW LEVEL SECURITY")
    op.execute(f"CREATE POLICY tenant_self ON platform.tenant USING (id = {tenant} OR id IN "
               f"(SELECT tenant_id FROM platform.membership WHERE user_id = {user})) WITH CHECK (true)")


